TWO_DECIMALS = 2


class DataStatistics:
    def mean(self, data):
        return round(sum(data) / len(data), TWO_DECIMALS)

    def _get_middle_value(self, sorted_data, index):
        return sorted_data[index]

    def median(self, data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        # Replace Nested Conditional with Guard Clauses
        if n % 2 == 0:
            middle = n // 2
            return round((self._get_middle_value(sorted_data, middle - 1) + self._get_middle_value(sorted_data, middle)) / 2, TWO_DECIMALS)
        else:
            middle = n // 2
            return self._get_middle_value(sorted_data, middle)

    def mode(self, data):
        counter = Counter(data)
        mode_count = max(counter.values())
        mode = [x for x, count in counter.items() if count == mode_count]
        return mode
